import React from 'react';
import { AbsoluteFill, interpolate, useCurrentFrame } from 'remotion';
import { COLORS, EASINGS } from '../../brand';
import { FONT_BODY, FONT_MONO } from '../../fonts';
import { CLAMP } from '../../lib/kit';
import { CaptionTrack, CoverImage, HookTitle, ProgressBar, SAFE, ShortBg, ToolCard, Watermark, secToFrame } from '../../lib/shorts';
import { WORDS } from './words';

// short-108: generated by the daily batch. Cover held at frame 0; closes on the cover.
export const compositionConfig = { id: 'Short108', durationInSeconds: 35.0, fps: 30, width: 1080, height: 1920 };

const B1 = secToFrame(3.622);
const B2 = secToFrame(9.381);
const B3 = secToFrame(14.571);
const B4 = secToFrame(21.641);
const B5 = secToFrame(29.35);
const CTA = secToFrame(31.649);

const FadeOut: React.FC<{ at: number; children: React.ReactNode }> = ({ at, children }) => {
  const frame = useCurrentFrame();
  const op = 1 - interpolate(frame, [at - 8, at + 2], [0, 1], { ...CLAMP, easing: EASINGS.easeIn });
  return <AbsoluteFill style={{ opacity: op }}>{children}</AbsoluteFill>;
};

const Line: React.FC<{ k: string; v: string; good?: boolean; bad?: boolean }> = ({ k, v, good, bad }) => (
  <div style={{ display: 'flex', justifyContent: 'space-between', fontFamily: FONT_MONO, fontSize: 32 }}>
    <span style={{ color: COLORS.d400 }}>{k}</span>
    <span style={{ color: bad ? COLORS.danger : good ? COLORS.signalAlt : COLORS.d300, fontWeight: good || bad ? 700 : 400 }}>{v}</span>
  </div>
);
const Panel: React.FC<{ children: React.ReactNode }> = ({ children }) => (
  <div style={{ background: COLORS.d900, borderRadius: 12, padding: '24px 26px', display: 'flex', flexDirection: 'column', gap: 16 }}>{children}</div>
);

const Short108: React.FC = () => {
  const frame = useCurrentFrame();
  const ctaOp = interpolate(frame, [CTA, CTA + 12], [0, 1], { ...CLAMP, easing: EASINGS.easeOut });
  return (
    <AbsoluteFill>
      <ShortBg />
      <FadeOut at={B1}>
        <CoverImage src="projects/short-108/cover.png" out={B1 - 10} />
        <HookTitle hold onDark kicker="PER MILLION TOKENS" lines={[{ text: "THREE AIS" }, { text: "$2 IN / $10 OUT", accent: true }]} />
      </FadeOut>
      <FadeOut at={B2 - 4}>
        <ToolCard name="GPT-6.1 Sol" tagline="OpenAI." chip="$2 / $10" at={B1}>
          <Panel>
            <Line k="input" v="$2" good />
            <Line k="output" v="$10" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B3 - 4}>
        <ToolCard name="Claude Sonnet 5.5" tagline="Anthropic." chip="$2 / $10" at={B2}>
          <Panel>
            <Line k="input" v="$2" good />
            <Line k="output" v="$10" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B4 - 4}>
        <ToolCard name="Gemini 4 Argon" tagline="Google." chip="$2 / $10" at={B3}>
          <Panel>
            <Line k="input" v="$2" good />
            <Line k="output" v="$10" good />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={B5 - 4}>
        <ToolCard name="Argon doubles" tagline="From December 1." chip="$4 / $20" at={B4} chipColor={COLORS.danger}>
          <Panel>
            <Line k="Dec 1 input" v="$4" bad />
            <Line k="Dec 1 output" v="$20" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <FadeOut at={CTA - 4}>
        <ToolCard name="Today vs December" tagline="Per million tokens." chip="DATE" at={B5} chipColor={COLORS.accent2}>
          <Panel>
            <Line k="GPT-6.1 Sol" v="$2 / $10" />
            <Line k="Claude Sonnet 5.5" v="$2 / $10" />
            <Line k="Argon after Dec 1" v="$4 / $20" bad />
          </Panel>
        </ToolCard>
      </FadeOut>
      <AbsoluteFill style={{ opacity: ctaOp }}>
        <CoverImage src="projects/short-108/cover.png" at={CTA} />
        <HookTitle hold onDark at={CTA} kicker="PER MILLION TOKENS" lines={[{ text: "THREE AIS" }, { text: "$2 IN / $10 OUT", accent: true }]} />
        <div style={{ position: 'absolute', left: SAFE.side, right: SAFE.side, top: SAFE.top + 520, textAlign: 'center', fontFamily: FONT_BODY, fontWeight: 600, fontSize: 44, color: 'rgba(255,255,255,0.82)' }}>
          Check the date.
        </div>
      </AbsoluteFill>
      <CaptionTrack words={WORDS} />
      <Watermark at={12} />
      <ProgressBar />
    </AbsoluteFill>
  );
};
export default Short108;
